import {projectNavigation} from './oncall-navigation.js';
import {escapeHtml as esc} from './message-format.js';
import {localInstant,localAt,resultValue} from './oncall-planning.js';
import {renderServiceStatus} from './service-status.js';
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const variant=x=>Object.keys(x||{})[0];
export function createOncallStatus({root,api,session,getMe}) {
 let generation=0,identity='';const clear=()=>{generation++;identity='';};
 const active=stamp=>stamp===generation&&identity===getMe()?.id;
 async function show(w,mode='status'){
  const stamp=++generation;identity=getMe()?.id;root.innerHTML='<p role="status">Loading status publication…</p>';
  try{const [view]=await api().oncallStatus(session.load(),w.project.id);if(!active(stamp))return;if(!view)throw Error('Your Hub account does not have access to this project.');paint(w,view,mode,stamp);}catch(e){if(active(stamp))root.innerHTML=`<h2>Status page unavailable</h2><p>${esc(e.message)}</p>`;}
 }
 function paint(w,v,mode,stamp){
  const c=v.config[0],page=v.page[0],zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',publicUrl=new URL('./support.html#status/'+encodeURIComponent(c?.slug||''),location.href).href;
  const input=(id,title,value='',attrs='')=>`<label for="${id}">${title}</label><input id="${id}" value="${esc(value)}" ${attrs}>`;
  const editor=mode!=='status',noticeId=/^status-\d+$/.test(mode)?BigInt(mode.slice(7)):0n,n=v.notices.find(n=>n.id===noticeId);
  const linked=/^status-new-\d+$/.test(mode)?BigInt(mode.slice(11)):0n;
  root.innerHTML=`<a class="back-link" href="#/oncall/${w.project.id}">← ${esc(w.project.name)}</a><div class="page-heading"><div><span class="eyebrow">ON-CALL · COMMUNICATION</span><h2>${editor?'Publish a status update':'Status page'}</h2><p class="lead">${c?c.audience.public===null?'Public updates · visible without signing in.':'Workspace updates · visible to signed-in Desk users.':'Start with an audience and the services you want to show.'}</p></div>${c?.enabled&&!editor?`<a class="button primary" href="#/oncall/${w.project.id}/status-new">Publish a notice ＋</a>`:''}</div>${projectNavigation(w,'status')}<p data-status-result role="status"></p>`;
  const message=text=>{const el=root.querySelector('[data-status-result]');if(el)el.textContent=text;};
  async function run(button,fn){if(!active(stamp)||button.disabled)return;button.disabled=true;message('Saving…');try{resultValue(await fn());if(active(stamp)){if(editor)location.hash=`#/oncall/${w.project.id}/status`;await show(w,'status');}}catch(e){if(active(stamp))message(e.message||'Connection interrupted. Refresh to check whether the update was saved.');}finally{if(button.isConnected)button.disabled=false;}}
  if(editor&&c?.enabled){
   if(noticeId&&!n){message('This notice is unavailable.');return;}
   const requestKey=key(),audience=variant(c.audience)==='public'?'anyone on the internet':'everyone signed in to this Desk workspace';
   root.insertAdjacentHTML('beforeend',`<form id="statusNotice" class="card oc-form"><h3>${n?'Add an update':'Publish a notice'}</h3><p class="oc-issues">This text will be visible to ${audience}. Write only information intended for this audience. Internal incident details are never copied automatically.</p>${input('noticeTitle','Title',n?.title||'','required maxlength="120" '+(n?'readonly':''))}<label for="noticeService">Affected services</label><select id="noticeService" multiple required ${n?'disabled':''}>${c.services.map(s=>`<option ${n?.services.includes(s)||c.services.length===1?'selected':''}>${esc(s)}</option>`).join('')}</select><div class="row"><div><label for="noticePhase">Progress</label><select id="noticePhase">${['investigating','identified','monitoring','resolved',...(!n||n.startsAt>0n?['scheduled','maintenance']:[])].map(s=>`<option value="${s}" ${variant(n?.phase)===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><div><label for="noticeImpact">Impact</label><select id="noticeImpact">${['degraded','outage','maintenance'].map(s=>`<option value="${s}" ${variant(n?.impact)===s?'selected':''}>${s}</option>`).join('')}</select></div></div><label for="noticeMessage">Update for your audience</label><textarea id="noticeMessage" required minlength="3" maxlength="1000" rows="5" placeholder="What is affected, what the team is doing, and when people can expect another update."></textarea><div id="maintenanceWindow" hidden>${input('maintenanceStart','Maintenance starts · '+esc(zone),n?.startsAt?localAt(Number(n.startsAt/1000000n),zone):'','type="datetime-local" '+(n?'readonly':''))}${input('maintenanceEnd','Expected end',n?.endsAt?localAt(Number(n.endsAt/1000000n),zone):'','type="datetime-local" '+(n?'readonly':''))}<p class="kv">The end time is an estimate. Publish a resolved update after checking recovery.</p></div>${input('noticeIncident','Related incident number · private, optional',String(n?.incidentId||linked||''),'type="number" min="1" '+(n?'readonly':''))}<label class="checkline"><input id="confirmPublication" type="checkbox" required> I reviewed this text for the selected audience.</label><div class="btnrow"><button class="primary">${n?'Publish update':'Publish notice'}</button><a class="button" href="#/oncall/${w.project.id}/status">Cancel</a></div></form>`);
   const phase=root.querySelector('#noticePhase');phase.onchange=()=>{const maintenance=['scheduled','maintenance'].includes(phase.value);root.querySelector('#maintenanceWindow').hidden=!maintenance;root.querySelectorAll('#maintenanceWindow input').forEach(x=>x.required=maintenance&&!n);if(maintenance)root.querySelector('#noticeImpact').value='maintenance';};phase.onchange();
   root.querySelector('form').onsubmit=e=>{e.preventDefault();try{const value=id=>root.querySelector('#'+id).value,scheduled=['scheduled','maintenance'].includes(value('noticePhase'));const payload={projectId:w.project.id,incidentId:BigInt(value('noticeIncident')||0),title:value('noticeTitle').trim(),message:value('noticeMessage').trim(),services:n?.services||[...root.querySelector('#noticeService').selectedOptions].map(o=>o.value),phase:{[value('noticePhase')]:null},impact:{[value('noticeImpact')]:null},startsAt:n?.startsAt||(scheduled?localInstant(value('maintenanceStart'),zone):0n),endsAt:n?.endsAt||(scheduled?localInstant(value('maintenanceEnd'),zone):0n)};run(e.submitter,()=>api().publishServiceNotice(session.load(),requestKey,n?.id||0n,n?.revision||0n,payload));}catch(e){message(e.message);}};return;
  }
  if(w.canManage){root.insertAdjacentHTML('beforeend',`<details class="card oc-form ss-admin-details" ${!c?'open':''}><summary>${c?'Page settings':'Set up this page'}</summary><form id="statusConfig">${input('statusTitle','Page title',c?.title||w.project.name,'required maxlength="80"')}${input('statusDescription','Short description',c?.description||'','maxlength="300"')}${input('statusSlug','Page address',c?.slug||'','required pattern="[a-z0-9-]{3,60}" placeholder="product-status"')}<label for="statusAudience">Who can read it?</label><select id="statusAudience"><option value="workspace">People signed in to Desk</option><option value="public" ${variant(c?.audience)==='public'?'selected':''}>Anyone · public internet</option></select><p class="kv">Changing the audience starts a fresh page. Previous notices stay private in this project’s history.</p><label for="statusServices">Services shown</label><select id="statusServices" multiple required>${w.project.services.map(s=>`<option ${!c||c.services.includes(s)?'selected':''}>${esc(s)}</option>`).join('')}</select>${input('statusRetention','Keep notices for · days',String(c?.retentionDays||90n),'type="number" min="30" max="365" required')}<label class="checkline"><input type="checkbox" id="statusEnabled" ${c?.enabled?'checked':''}> Enable this status page</label><button>Save page settings</button></form></details>`);
   root.querySelector('#statusConfig').onsubmit=e=>{e.preventDefault();const value=id=>root.querySelector('#'+id).value;run(e.submitter,()=>api().setOncallStatus(session.load(),w.project.id,c?.revision||0n,{title:value('statusTitle').trim(),description:value('statusDescription').trim(),slug:value('statusSlug').trim(),audience:{[value('statusAudience')]:null},services:[...root.querySelector('#statusServices').selectedOptions].map(o=>o.value),retentionDays:BigInt(value('statusRetention')),enabled:root.querySelector('#statusEnabled').checked}));};
  }
  if(!c){if(!w.canManage)root.insertAdjacentHTML('beforeend','<section class="card oc-empty"><h3>No status page yet.</h3><p>A Desk administrator needs to select the audience and enable this project’s status page.</p></section>');return;}
  root.insertAdjacentHTML('beforeend',`<div class="ss-admin-toolbar"><p>${c.enabled?'Enabled':'Disabled'} · ${variant(c.audience)==='public'?'Public page':'Workspace page'}</p>${c.enabled&&variant(c.audience)==='public'?`<a class="button" href="${esc(publicUrl)}" target="_blank" rel="noopener noreferrer">Open public page ↗</a>`:'<a class="button" href="#/service-status">Workspace status ↗</a>'}</div>${c.enabled?`<details class="card oc-form ss-admin-details"><summary>Confirm operational services</summary><form id="statusConfirm"><p>Use after checking the service yourself. Active notices still take precedence.</p><label for="healthyServices">Services checked</label><select id="healthyServices" multiple required>${c.services.map(s=>`<option>${esc(s)}</option>`).join('')}</select><label for="validHours">Confirmation remains valid for</label><select id="validHours"><option value="4">4 hours</option><option value="24" selected>24 hours</option><option value="168">7 days</option></select><button>Confirm operational</button></form></details>`:''}<div class="ss-editor-preview">${page?renderServiceStatus(page):''}</div><details class="oc-history"><summary>Notice management & history</summary>${v.notices.map(n=>`<div class="oc-availability-row"><div><strong>${esc(n.title)}</strong><p>${esc(variant(n.phase))}${n.withdrawnAt?' · withdrawn':''}${n.generation!==c.generation?' · previous audience':''}${n.incidentId?` · <a href="#/oncall/${w.project.id}/incident-${n.incidentId}">Incident OC-${n.incidentId}</a>`:''}</p></div><div class="btnrow">${!n.withdrawnAt&&n.generation===c.generation?`${variant(n.phase)!=='resolved'&&c.enabled?`<a class="button" href="#/oncall/${w.project.id}/status-${n.id}">Add update</a>`:''}<button data-withdraw="${n.id}">Withdraw</button>`:''}</div></div>`).join('')||'<p>No notices published yet.</p>'}</details>`);
  const confirm=root.querySelector('#statusConfirm');if(confirm)confirm.onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().confirmServiceStatus(session.load(),w.project.id,c.revision,[...root.querySelector('#healthyServices').selectedOptions].map(o=>o.value),BigInt(root.querySelector('#validHours').value)));};
  root.querySelectorAll('[data-withdraw]').forEach(b=>b.onclick=()=>{const n=v.notices.find(n=>String(n.id)===b.dataset.withdraw);run(b,()=>api().withdrawServiceNotice(session.load(),n.id,n.revision));});
 }
 return{show,clear};
}
